  bg:{position:"absolute",inset:0,backgroundSize:"cover",backgroundPosition:"center"},
  ov:{position:"absolute",inset:0,background:"rgba(0,0,0,0.55)"},
  charSprite:{position:"absolute",bottom:"14%",height:"72%",objectFit:"contain",zIndex:2,filter:"drop-shadow(0 0 30px rgba(0,0,0,0.8))"},
