  protagRox:{position:"absolute",right:"8%",bottom:"10%",height:"60%",objectFit:"contain",zIndex:2,opacity:0.85},
  vChar:{position:"absolute",left:"5%",bottom:"12%",height:"70%",objectFit:"contain",zIndex:2,filter:"drop-shadow(0 0 20px rgba(201,168,76,0.3))"},
  dBox:{position:"absolute",bottom:"4%",left:"50%",transform:"translateX(-50%)",width:"88%",maxWidth:"860px",background:"linear-gradient(135deg,rgba(13,11,8,0.97),rgba(30,20,10,0.97))",border:`1px solid ${GOLD}`,borderRadius:"4px",padding:"20px 28px 18px",zIndex:10,boxShadow:`0 0 40px rgba(201,168,76,0.15)`},
  nBox:{position:"absolute",bottom:"4%",left:"50%",transform:"translateX(-50%)",width:"88%",maxWidth:"860px",background:"rgba(8,6,4,0.9)",borderTop:`2px solid ${GOLD}`,padding:"18px 28px 16px",zIndex:10},
  speaker:{fontFamily:"'Cinzel', serif",fontSize:"0.75rem",letterSpacing:"0.18em",color:GOLD,marginBottom:"8px",textTransform:"uppercase"},
  dText:{fontFamily:"'EB Garamond', serif",fontSize:"1.15rem",lineHeight:1.7,color:"#f0e8d8"},
  nText:{fontFamily:"'EB Garamond', serif",fontSize:"1.1rem",lineHeight:1.75,color:"#d8cfc0",fontStyle:"italic"},
  arrow:{position:"absolute",right:"16px",bottom:"14px",color:GOLD,fontSize:"0.9rem",animation:"pulse 1.2s infinite"},
  crowdImg:{position:"absolute",bottom:0,left:"50%",transform:"translateX(-50%)",width:"100%",maxWidth:"900px",objectFit:"contain",zIndex:2,opacity:0.9},
  crowdBubble:{position:"absolute",top:"18%",left:"50%",transform:"translateX(-50%)",background:"rgba(13,11,8,0.92)",border:`1px solid ${GOLD}`,borderRadius:"6px",padding:"20px 32px",zIndex:10,textAlign:"center",maxWidth:"500px"},
